require "pact_broker/matrix/matrix_row"
require "pact_broker/matrix/selector_resolver"
require "pact_broker/matrix/unresolved_selector"

module PactBroker
  module Matrix
    describe MatrixRow do
      def resolve(*attributes_list)
        SelectorResolver.resolve_specified_selectors(
          attributes_list.collect { |attributes| UnresolvedSelector.new(attributes) }, []
        )
      end

      # The SELECT list generated by select_pact_columns_with_aliases/select_verification_columns_with_aliases
      # always includes both the id column and the version id column, regardless of what
      # the WHERE clause filters on. Assertions about which column is actually
      # being filtered on must be scoped to the WHERE fragment, not the whole
      # statement, or they pass/fail for the wrong reason.
      def where_clause_for(dataset)
        sql = dataset.sql
        raise "Expected #{sql.inspect} to contain a WHERE clause" unless sql.include?(" WHERE ")
        sql.split(" WHERE ").last
      end

      describe "where_consumer_version_matches_selectors" do
        before do
          td.create_pact_with_hierarchy("Foo", "1", "Bar")
            .create_consumer_version("2")
            .create_pact
            .create_consumer_version("3")
            .create_pact
        end

        def dataset_for(selectors)
          MatrixRow.select_pact_columns_with_aliases.from_self(alias: :p).where_consumer_version_matches_selectors(selectors)
        end

        context "for a selector that specifies a version" do
          let(:selectors) { resolve({ pacticipant_name: "Foo", pacticipant_version_number: "2" }) }

          it "returns only the rows for that version" do
            expect(dataset_for(selectors).all.collect(&:consumer_version_id)).to eq [selectors.first[:pacticipant_version_id]]
          end

          it "filters on consumer_version_id" do
            expect(where_clause_for(dataset_for(selectors))).to include "consumer_version_id"
          end

          # The version id is already resolved, so this must not build a
          # per-selector UNION arm, nor re-resolve the pacticipant name.
          it "does not build a UNION or look up pacticipants by name" do
            sql = dataset_for(selectors).sql

            expect(sql).to_not include "UNION"
            expect(sql).to_not include "pacticipants"
          end
        end

        context "for a selector that specifies a version that does not exist" do
          let(:selectors) { resolve({ pacticipant_name: "Foo", pacticipant_version_number: "999" }) }

          it "returns no rows" do
            expect(dataset_for(selectors).all).to be_empty
          end
        end

        # matching_one_selector_for_either_consumer_or_provider passes its selectors
        # unfiltered, so a name-only selector arrives here with no version id at all.
        # Filtering on the version id would render IN (NULL) and silently return an
        # empty matrix for /matrix?q[][pacticipant]=Foo.
        context "for a name-only selector" do
          let(:selectors) { resolve({ pacticipant_name: "Foo" }) }

          it "returns the rows for every version of that pacticipant" do
            expect(dataset_for(selectors).all.size).to eq 3
          end

          it "filters on consumer_id, not consumer_version_id" do
            where = where_clause_for(dataset_for(selectors))

            expect(where).to include "consumer_id"
            expect(where).to_not include "consumer_version_id"
          end
        end

        context "for a mixture of both kinds" do
          let(:selectors) { resolve({ pacticipant_name: "Foo", pacticipant_version_number: "2" }, { pacticipant_name: "Bar" }) }

          it "builds a disjunction of the two criteria" do
            where = where_clause_for(dataset_for(selectors))

            expect(where).to include "consumer_version_id"
            expect(where).to include "consumer_id"
            expect(where).to include "OR"
          end
        end

        # The id list must stay flat as selectors are added — one literal per
        # selector, never one subquery per selector.
        context "as the number of selectors grows" do
          let(:selectors) do
            resolve(
              { pacticipant_name: "Foo", pacticipant_version_number: "1" },
              { pacticipant_name: "Foo", pacticipant_version_number: "2" },
              { pacticipant_name: "Foo", pacticipant_version_number: "3" }
            )
          end

          it "renders every id into one flat list with no UNION" do
            sql = dataset_for(selectors).sql
            where = where_clause_for(dataset_for(selectors))
            ids = selectors.collect { |s| s[:pacticipant_version_id] }

            expect(sql).to_not include "UNION"
            expect(where).to match(/IN \(#{ids.join(", ")}\)/)
          end
        end

        context "when no selectors are provided" do
          let(:selectors) { [] }

          it "raises an error rather than matching every row" do
            expect { dataset_for(selectors) }.to raise_error(ArgumentError)
          end
        end
      end

      describe "where_provider_version_matches_selectors" do
        before do
          td.create_pact_with_hierarchy("Foo", "1", "Bar")
            .create_verification(provider_version: "10", success: true)
            .create_verification(provider_version: "20", number: 2, success: true)
            .create_verification(provider_version: "30", number: 3, success: true)
        end

        def dataset_for(selectors)
          MatrixRow::Verification.select_verification_columns_with_aliases.where_provider_version_matches_selectors(selectors)
        end

        context "for a selector that specifies a version" do
          let(:selectors) { resolve({ pacticipant_name: "Bar", pacticipant_version_number: "20" }) }

          it "returns only the verifications by that provider version" do
            expect(dataset_for(selectors).all.collect(&:provider_version_id)).to eq [selectors.first[:pacticipant_version_id]]
          end

          it "filters on provider_version_id" do
            expect(where_clause_for(dataset_for(selectors))).to include "provider_version_id"
          end

          it "does not build a UNION or look up pacticipants by name" do
            sql = dataset_for(selectors).sql

            expect(sql).to_not include "UNION"
            expect(sql).to_not include "pacticipants"
          end
        end

        context "for a selector that specifies a version that does not exist" do
          let(:selectors) { resolve({ pacticipant_name: "Bar", pacticipant_version_number: "999" }) }

          it "returns no rows" do
            expect(dataset_for(selectors).all).to be_empty
          end
        end

        # matching_selectors_as_provider_for_any_consumer passes its selectors
        # unfiltered, so name-only selectors reach here without a version id.
        context "for a name-only selector" do
          let(:selectors) { resolve({ pacticipant_name: "Bar" }) }

          it "returns the verifications by every version of that provider" do
            expect(dataset_for(selectors).all.size).to eq 3
          end

          it "filters on provider_id, not provider_version_id" do
            where = where_clause_for(dataset_for(selectors))

            expect(where).to include "provider_id"
            expect(where).to_not include "provider_version_id"
          end
        end

        context "for a mixture of both kinds" do
          let(:selectors) { resolve({ pacticipant_name: "Bar", pacticipant_version_number: "20" }, { pacticipant_name: "Foo" }) }

          it "builds a disjunction of the two criteria" do
            where = where_clause_for(dataset_for(selectors))

            expect(where).to include "provider_version_id"
            expect(where).to include "provider_id"
            expect(where).to include "OR"
          end
        end

        # The id list must stay flat as selectors are added — one literal per
        # selector, never one subquery per selector.
        context "as the number of selectors grows" do
          let(:selectors) do
            resolve(
              { pacticipant_name: "Bar", pacticipant_version_number: "10" },
              { pacticipant_name: "Bar", pacticipant_version_number: "20" },
              { pacticipant_name: "Bar", pacticipant_version_number: "30" }
            )
          end

          it "renders every id into one flat list with no UNION" do
            sql = dataset_for(selectors).sql
            where = where_clause_for(dataset_for(selectors))
            ids = selectors.collect { |s| s[:pacticipant_version_id] }

            expect(sql).to_not include "UNION"
            expect(where).to match(/IN \(#{ids.join(", ")}\)/)
          end
        end

        context "when no selectors are provided" do
          let(:selectors) { [] }

          it "raises an error rather than matching every row" do
            expect { dataset_for(selectors) }.to raise_error(ArgumentError)
          end
        end
      end
    end
  end
end
